SET local check_function_bodies = off;

CREATE SCHEMA "api";

CREATE SCHEMA "geo";

CREATE SCHEMA "live";

CREATE SCHEMA "ops";

CREATE SCHEMA "ref";

CREATE EXTENSION "btree_gist" SCHEMA "public";

CREATE EXTENSION "pg_cron";

CREATE EXTENSION "pg_trgm" SCHEMA "public";

CREATE EXTENSION "postgis" SCHEMA "public";

CREATE TABLE "geo"."area" (
  "id"        bigint                             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "kind"      text                               NOT NULL,
  "code"      text,
  "name"      text,
  "name_alt"  text,
  "rank"      smallint,
  "area_km2"  double precision,
  "source_id" bigint,
  "attrs"     jsonb                              NOT NULL DEFAULT '{}'::jsonb,
  "geom"      public.geometry(MultiPolygon,4326),
  "geom_lo"   public.geometry(MultiPolygon,4326),
  "geom_mid"  public.geometry(MultiPolygon,4326),
  "label_pt"  public.geometry(Point,4326),
  CONSTRAINT "area_kind_code_key" UNIQUE (kind, code),
  CONSTRAINT "area_pkey" PRIMARY KEY (id)
);

CREATE TABLE "geo"."gauge_model" (
  "site_id"         bigint                   NOT NULL,
  "normal"          double precision[],
  "normal_years"    integer,
  "beta"            double precision[],
  "sd"              double precision,
  "r2"              double precision,
  "trained_through" date,
  "built_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "gauge_model_pkey" PRIMARY KEY (site_id)
);

CREATE TABLE "geo"."river_link" (
  "id"              bigint                            GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "os_id"           text                              NOT NULL,
  "river_id"        bigint,
  "waterbody_id"    bigint,
  "form"            text,
  "name"            text,
  "length_m"        real,
  "start_node_id"   bigint,
  "end_node_id"     bigint,
  "flow_direction"  text,
  "strahler"        smallint,
  "dist_to_mouth_m" double precision,
  "upstream_km"     real,
  "size_class"      smallint,
  "river_class"     smallint,
  "geom"            public.geometry(LineString,4326),
  "geom_bng"        public.geometry(LineString,27700),
  CONSTRAINT "river_link_os_id_key" UNIQUE (os_id),
  CONSTRAINT "river_link_pkey" PRIMARY KEY (id)
);

CREATE TABLE "geo"."river" (
  "id"              bigint                                GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "slug"            text                                  NOT NULL,
  "name"            text                                  NOT NULL,
  "name_cy"         text,
  "parent_river_id" bigint,
  "mouth_node_id"   bigint,
  "source_node_id"  bigint,
  "length_km"       double precision,
  "strahler_max"    smallint,
  "river_class"     smallint,
  "aliases"         text[]                                NOT NULL DEFAULT '{}'::text[],
  "research"        jsonb                                 NOT NULL DEFAULT '[]'::jsonb,
  "geom"            public.geometry(MultiLineString,4326),
  "label_pt"        public.geometry(Point,4326),
  CONSTRAINT "river_pkey" PRIMARY KEY (id),
  CONSTRAINT "river_slug_key" UNIQUE (slug)
);

CREATE TABLE "geo"."site_key" (
  "scheme"  text   NOT NULL,
  "value"   text   NOT NULL,
  "site_id" bigint NOT NULL,
  CONSTRAINT "site_key_pkey" PRIMARY KEY (scheme, VALUE)
);

CREATE TABLE "geo"."site" (
  "id"                bigint                       GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "kind"              text                         NOT NULL,
  "name"              text,
  "country"           text,
  "operator_id"       bigint,
  "status"            text,
  "river_link_id"     bigint,
  "river_id"          bigint,
  "waterbody_id"      bigint,
  "snap_distance_m"   real,
  "dist_to_mouth_m"   double precision,
  "river_name_raw"    text,
  "primary_source_id" bigint,
  "attrs"             jsonb                        NOT NULL DEFAULT '{}'::jsonb,
  "geom"              public.geometry(Point,4326),
  "geom_bng"          public.geometry(Point,27700),
  CONSTRAINT "site_pkey" PRIMARY KEY (id)
);

CREATE TABLE "geo"."waterbody" (
  "id"                    bigint                                GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "wb_code"               text                                  NOT NULL,
  "name"                  text,
  "category"              text,
  "designation"           text,
  "country"               text,
  "river_id"              bigint,
  "rbd"                   text,
  "management_catchment"  text,
  "operational_catchment" text,
  "area_km2"              double precision,
  "length_km"             double precision,
  "source_id"             bigint,
  "ids"                   jsonb                                 NOT NULL DEFAULT '{}'::jsonb,
  "classes"               jsonb                                 NOT NULL DEFAULT '{}'::jsonb,
  "reasons"               jsonb                                 NOT NULL DEFAULT '[]'::jsonb,
  "apportionment"         jsonb                                 NOT NULL DEFAULT '[]'::jsonb,
  "radar_cells"           integer[],
  "catchment_geom"        public.geometry(MultiPolygon,4326),
  "line_geom"             public.geometry(MultiLineString,4326),
