CREATE VIEW "live"."map_point" AS  SELECT 'overflows'::text AS layer,
    s.id,
    s.geom,
    COALESCE((n.state = 'discharging'::text), false) AS hot,
    jsonb_build_object('n', s.name, 'co', org.name, 'st', COALESCE(n.state, 'unknown'::text), 'since', n.since, 'rw', (s.attrs ->> 'receiving'::text), 'rv', r.slug, 'rn', r.name, 'sp', ((s.attrs ->> 'spills'::text))::integer, 'hr', round(((s.attrs ->> 'spill_hours'::text))::numeric), 'rep', n.at, 'ls', (n.detail -> 'last_event_start'::text), 'le', (n.detail -> 'last_event_end'::text), 'mon', COALESCE((n.state = ANY (ARRAY['discharging'::text, 'not_discharging'::text])), false)) AS props
   FROM (((geo.site s
     LEFT JOIN live.site_now n ON ((n.site_id = s.id)))
     LEFT JOIN ref.organisation org ON ((org.id = s.operator_id)))
     LEFT JOIN geo.river r ON ((r.id = s.river_id)))
  WHERE (s.kind = 'storm_overflow'::text)
UNION ALL
 SELECT 'bathing'::text AS layer,
    s.id,
    s.geom,
    COALESCE(((s.attrs ->> 'class'::text) = 'poor'::text), false) AS hot,
    jsonb_build_object('n', s.name, 'wt', (s.attrs ->> 'water_type'::text), 'cl', (s.attrs ->> 'class'::text), 'cy', ((s.attrs ->> 'class_year'::text))::integer, 'at', ec.latest_at, 'ec', ec.latest_value, 'cn', ec.latest_censor, 'rv', r.slug, 'rn', r.name) AS props
   FROM ((geo.site s
     LEFT JOIN LATERAL ( SELECT se.latest_at,
            se.latest_value,
            se.latest_censor
           FROM live.series se
          WHERE ((se.site_id = s.id) AND (se.source_series_key ~~ 'bwq:%:ecoli'::text))
          ORDER BY se.latest_at DESC NULLS LAST
         LIMIT 1) ec ON (true))
     LEFT JOIN geo.river r ON ((r.id = s.river_id)))
  WHERE (s.kind = 'bathing_water'::text)
UNION ALL
 SELECT 'gauges'::text AS layer,
    s.id,
    s.geom,
    (g.rank >= 3) AS hot,
    jsonb_build_object('n', s.name, 'b', g.rank, 'bd', g.state, 'lv', round((g.stage)::numeric, 2), 'th', ((g.detail ->> 'typical_high'::text))::double precision, 'ix', round(((g.detail ->> 'level_index'::text))::numeric, 2), 'q', round((g.flow)::numeric, 3), 'qi', round(((g.detail ->> 'flow_index'::text))::numeric, 2), 'p', round((g.flow_pct)::numeric), 'at', g.at, 'rv', r.slug, 'rn', r.name) AS props
   FROM ((live.site_now g
     JOIN geo.site s ON ((s.id = g.site_id)))
     LEFT JOIN geo.river r ON ((r.id = s.river_id)))
  WHERE (g.kind = 'gauge'::text)
UNION ALL
 SELECT 'bridges'::text AS layer,
    s.id,
    s.geom,
    false AS hot,
    jsonb_build_object('n', s.name, 'rv', r.slug, 'rn', r.name, 'wb', w.name) AS props
   FROM ((geo.site s
     LEFT JOIN geo.river r ON ((r.id = s.river_id)))
     LEFT JOIN geo.waterbody w ON ((w.id = s.waterbody_id)))
  WHERE (s.kind = 'bridge'::text)
UNION ALL
 SELECT 'sewage_works'::text AS layer,
    s.id,
    s.geom,
    false AS hot,
    jsonb_strip_nulls(jsonb_build_object('n', s.name, 'co', org.name, 'rw', s.river_name_raw, 'm', COALESCE(((s.attrs ->> 'measured'::text))::boolean, false), 'pm', (s.attrs ->> 'permit_ref'::text), 'rv', r.slug, 'rn', r.name, 'at', n.at, 'nh', (n.detail #>> '{latest,ammonia_total_n,v}'::text[]), 'nhc', (n.detail #>> '{latest,ammonia_total_n,c}'::text[]), 'bod', (n.detail #>> '{latest,bod5,v}'::text[]), 'ss', (n.detail #>> '{latest,suspended_solids,v}'::text[]), 'tp', (n.detail #>> '{latest,phosphorus_total,v}'::text[]))) AS props
   FROM (((geo.site s
     LEFT JOIN live.site_now n ON (((n.site_id = s.id) AND (n.kind = 'works'::text))))
     LEFT JOIN ref.organisation org ON ((org.id = s.operator_id)))
     LEFT JOIN geo.river r ON ((r.id = s.river_id)))
  WHERE ((s.kind = 'sewage_works'::text) AND (s.attrs ? 'works'::text))
UNION ALL
 SELECT 'citizen'::text AS layer,
    s.id,
    s.geom,
    false AS hot,
    jsonb_strip_nulls(jsonb_build_object('n', s.name, 'org', (s.attrs ->> 'organisation'::text), 'at', v.last_visit, 'nv', v.visits, 'p', round((ph.latest_value)::numeric, 3), 'rv', r.slug, 'rn', r.name)) AS props
   FROM (((geo.site s
     JOIN LATERAL ( SELECT max(sv.surveyed_at) AS last_visit,
            count(*) AS visits
           FROM live.survey sv
          WHERE ((sv.site_id = s.id) AND (sv.kind = 'citizen_weekly'::text))) v ON (true))
     LEFT JOIN LATERAL ( SELECT se.latest_value
           FROM (live.series se
             JOIN ref.parameter p ON ((p.id = se.parameter_id)))
          WHERE ((se.site_id = s.id) AND (p.code = 'phosphorus_reactive'::text) AND (se.evidence_class = 'citizen_science'::text))
          ORDER BY se.latest_at DESC NULLS LAST
         LIMIT 1) ph ON (true))
     LEFT JOIN geo.river r ON ((r.id = s.river_id)))
  WHERE ((s.kind = 'survey_site'::text) AND (v.visits > 0));

CREATE VIEW "ops"."job_freshness" WITH (security_invoker=true) AS  SELECT name,
    source_slug,
    enabled,
    interval_minutes,
    max_lag_minutes,
    last_status,
    last_started_at,
    last_finished_at,
    round((EXTRACT(epoch FROM (now() - last_finished_at)) / (60)::numeric)) AS minutes_since_finish,
    COALESCE((last_status = ANY (ARRAY['failed'::text, 'timeout'::text])), false) AS failing,
    (enabled AND ((last_finished_at IS NULL) OR ((EXTRACT(epoch FROM (now() - last_finished_at)) / (60)::numeric) > (COALESCE(max_lag_minutes, (interval_minutes * 3)))::numeric))) AS stale
   FROM ops.etl_job;

